<script setup lang="ts">
const props=withDefaults(defineProps<{locale?:'nl'|'en'}>(),{locale:'nl'})
const nl=computed(()=>props.locale==='nl')
const p=reactive({revenue:40.2,dividend:10,tolerance:6,sensitivity:7,shape:1.65,sponsorLift:18,coverage:65,mobility:1.1,absorption:4.5,socialMultiplier:1.45,crowdingOut:18,administration:6,fanSensitivity:.45})
const presets={
  cautious:{tolerance:4,sensitivity:10,sponsorLift:4,coverage:35,absorption:3,socialMultiplier:1.05,crowdingOut:30},
  middle:{tolerance:6,sensitivity:7,sponsorLift:18,coverage:65,absorption:4.5,socialMultiplier:1.45,crowdingOut:18},
  optimistic:{tolerance:10,sensitivity:4,sponsorLift:35,coverage:90,absorption:7,socialMultiplier:1.9,crowdingOut:8},
  break:{tolerance:0,sensitivity:18,sponsorLift:0,coverage:10,absorption:1.8,socialMultiplier:.7,crowdingOut:45}
}
const apply=(key:keyof typeof presets)=>Object.assign(p,presets[key])
const result=computed(()=>calculateSportDividend(p))
const optima=computed(()=>sportDividendOptima(p))
const euro=(v:number)=>new Intl.NumberFormat(nl.value?'nl-NL':'en-GB',{style:'currency',currency:'EUR',maximumFractionDigits:1}).format(v)+' '+(nl.value?'mld.':'bn')
const pct=(v:number)=>new Intl.NumberFormat(nl.value?'nl-NL':'en-GB',{style:'percent',maximumFractionDigits:1}).format(v)
const chart=computed(()=>{const w=900,h=360,m={l:66,r:28,t:24,b:44},iw=w-m.l-m.r,ih=h-m.t-m.b;const rows=optima.value.curve;const max=Math.max(...rows.flatMap(x=>[x.revenue,x.net,x.total]))*1.05;const x=(rate:number)=>m.l+rate/70*iw;const y=(value:number)=>m.t+ih-value/max*ih;const path=(key:'revenue'|'net'|'total')=>rows.map((row,i)=>`${i?'L':'M'} ${x(row.rate)} ${y(row[key])}`).join(' ');return{w,h,m,iw,ih,x,y,path,max,ticks:Array.from({length:5},(_,i)=>max*i/4)}})
const policies=computed(()=>[
  {name:nl.value?'Omzetdividend':'Revenue dividend',base:100,distortion:1},
  {name:nl.value?'Mediarechtenbijdrage':'Media-rights contribution',base:27,distortion:.72},
  {name:nl.value?'Transferheffing':'Transfer levy',base:18,distortion:.82},
  {name:nl.value?'Salarisbijdrage':'Salary contribution',base:25,distortion:1.15},
  {name:nl.value?'Persoonlijke rechten':'Personal rights',base:8,distortion:1.35}
].map(x=>({...x,yield:x.base*p.dividend/100,pressure:x.distortion*p.dividend})))
</script>

<template>
  <section class="sport-model" data-analytics-model="sport-dividend">
    <header><p class="eyebrow">{{nl?'INTERACTIEVE SYSTEEMVERKENNER':'INTERACTIVE SYSTEM EXPLORER'}}</p><h2>{{nl?'Hoe ver kan herverdeling gaan?':'How far can redistribution go?'}}</h2><p>{{nl?'Verander de aannames en bekijk wanneer een hoger percentage meer oplevert, wanneer de markt krimpt en waarom het financiële en maatschappelijke optimum uiteenlopen.':'Change the assumptions to see when a higher rate raises more, when the market contracts, and why the financial and social optima differ.'}}</p></header>
    <div class="presets"><span>{{nl?'Scenario':'Scenario'}}</span><button @click="apply('cautious')">{{nl?'Voorzichtig':'Cautious'}}</button><button @click="apply('middle')">{{nl?'Midden':'Middle'}}</button><button @click="apply('optimistic')">{{nl?'Optimistisch':'Optimistic'}}</button><button @click="apply('break')">{{nl?'Breek het idee':'Break the idea'}}</button></div>
    <div class="primary"><label>{{nl?'Sportdividend':'Sport dividend'}} <output>{{p.dividend}}%</output><input v-model.number="p.dividend" type="range" min="0" max="70"></label><div><span>{{nl?'Professionele omzet':'Professional revenue'}}</span><strong>{{euro(result.revenue)}}</strong></div><div><span>{{nl?'Netto naar sportbasis':'Net to grassroots'}}</span><strong>{{euro(result.net)}}</strong></div><div><span>{{nl?'Geschatte totale waarde':'Estimated total value'}}</span><strong>{{euro(result.total)}}</strong></div></div>
    <div class="chart-scroll"><svg :viewBox="`0 0 ${chart.w} ${chart.h}`" role="img"><g v-for="tick in chart.ticks" :key="tick"><line :x1="chart.m.l" :x2="chart.m.l+chart.iw" :y1="chart.y(tick)" :y2="chart.y(tick)"/><text :x="chart.m.l-9" :y="chart.y(tick)+4" text-anchor="end">{{tick.toFixed(0)}}</text></g><path :d="chart.path('revenue')" class="revenue"/><path :d="chart.path('net')" class="grassroots"/><path :d="chart.path('total')" class="value"/><line :x1="chart.x(p.dividend)" :x2="chart.x(p.dividend)" :y1="chart.m.t" :y2="chart.h-chart.m.b" class="selected"/><g v-for="x in [0,10,20,30,40,50,60,70]" :key="x"><text :x="chart.x(x)" :y="chart.h-16" text-anchor="middle">{{x}}%</text></g></svg></div>
    <div class="legend"><span class="revenue">{{nl?'Professionele omzet':'Professional revenue'}}</span><span class="grassroots">{{nl?'Netto sportbasis':'Net grassroots funding'}}</span><span class="value">{{nl?'Geschatte totale waarde':'Estimated total value'}}</span></div>
    <div class="optima"><div><span>{{nl?'Meeste geld voor sportbasis':'Maximum grassroots funding'}}</span><strong>{{optima.funding.rate}}%</strong></div><div><span>{{nl?'Hoogste geschatte totale waarde':'Highest estimated total value'}}</span><strong>{{optima.social.rate}}%</strong></div><div><span>{{nl?'Marktverlies bij huidige keuze':'Market loss at current choice'}}</span><strong>{{pct(result.marketLoss)}}</strong></div></div>
    <details><summary>{{nl?'Geavanceerde scenarioaannames':'Advanced scenario assumptions'}}</summary><div class="controls"><label>{{nl?'Tolerantiegrens':'Tolerance'}}<input v-model.number="p.tolerance" type="range" min="0" max="25"><output>{{p.tolerance}}%</output></label><label>{{nl?'Marktgevoeligheid':'Market sensitivity'}}<input v-model.number="p.sensitivity" type="range" min="1" max="20"><output>{{p.sensitivity}}</output></label><label>{{nl?'Internationale dekking':'International coverage'}}<input v-model.number="p.coverage" type="range" min="0" max="100"><output>{{p.coverage}}%</output></label><label>{{nl?'Sponsorbonus':'Sponsor lift'}}<input v-model.number="p.sponsorLift" type="range" min="0" max="60"><output>{{p.sponsorLift}}%</output></label><label>{{nl?'Absorptiecapaciteit':'Absorption capacity'}}<input v-model.number="p.absorption" type="range" min="1" max="12" step=".5"><output>{{euro(p.absorption)}}</output></label><label>{{nl?'Maatschappelijke multiplier':'Social multiplier'}}<input v-model.number="p.socialMultiplier" type="range" min=".5" max="3" step=".05"><output>{{p.socialMultiplier}}</output></label><label>{{nl?'Verdringing bestaand geld':'Crowding out'}}<input v-model.number="p.crowdingOut" type="range" min="0" max="60"><output>{{p.crowdingOut}}%</output></label></div></details>
    <section class="policy"><h3>{{nl?'Dezelfde heffing werkt niet overal hetzelfde':'The same rate does not work the same everywhere'}}</h3><div v-for="item in policies" :key="item.name"><span>{{item.name}}</span><i><b :style="{width:`${Math.min(100,item.pressure)}%`}"/></i><strong>{{euro(item.yield)}}</strong></div><p>{{nl?'De balk toont relatieve verstoringsdruk binnen dit illustratieve scenario, niet een gemeten elasticiteit.':'The bar shows relative distortion pressure in this illustrative scenario, not a measured elasticity.'}}</p></section>
    <footer><p><strong>{{nl?'Geobserveerd':'Observed'}}:</strong> {{nl?'€40,2 miljard Europese voetbalomzet in 2024/25, exclusief transfers.':'€40.2 billion European football revenue in 2024/25, excluding transfers.'}}</p><p><strong>{{nl?'Scenario':'Scenario'}}:</strong> {{nl?'alle elasticiteiten, sponsorbonus, absorptie, verdringing en maatschappelijke waardering. De uitkomst is geen beleidsraming.':'all elasticities, sponsor lift, absorption, crowding out and social valuation. The result is not a policy forecast.'}}</p></footer>
  </section>
</template>

