y{padding:14px 17px;cursor:pointer;font-weight:600;font-size:.78rem}.controls{display:grid;grid-template-columns:repeat(2,1fr);gap:14px 24px;padding:18px;border-top:1px solid var(--line)}.controls label{display:grid;grid-template-columns:1fr 130px 60px;align-items:center;font-size:.7rem}.controls input{accent-color:var(--accent)}.controls output{text-align:right}.policy{margin-top:32px}.policy h3{font-size:1.1rem}.policy>div{display:grid;grid-template-columns:180px 1fr 90px;gap:12px;align-items:center;padding:7px 0;font-size:.72rem}.policy i{height:8px;background:#d7ddd8}.policy b{display:block;height:100%;background:#d46a47}.policy strong{text-align:right}.policy p,footer{font-size:.68rem;color:var(--muted)}footer{border-top:1px solid #c8d0c9;margin-top:28px;padding-top:16px}footer p{margin:.5rem 0}@media(max-width:760px){.sport-model{margin:3rem 0;width:calc(100vw - 32px);padding:25px 15px}.primary,.optima{grid-template-columns:1fr}.controls{grid-template-columns:1fr}.controls label{grid-template-columns:1fr 110px 55px}.policy>div{grid-template-columns:125px 1fr 75px}}
